const O=[["#10482","Jenna Kim","Today, 09:14",2,"$164.00","paid"],["#10481","Omar Said","Today, 08:52",1,"$399.00","pending"],["#10480","Chloe Baker","Yesterday",3,"$212.50","shipped"],["#10479","Raj Patel","Yesterday",1,"$80.00","returned"],["#10478","Anna Novak","12 Oct",4,"$318.90","shipped"],["#10477","Tom Reed","12 Oct",1,"$59.00","paid"],["#10476","Lucia Gomez","11 Oct",2,"$146.00","pending"]];
const cols=["#F97316","#2563EB","#16A34A","#DB2777","#7C3AED","#0891B2","#CA8A04"];
function orders(f){document.getElementById('orders').innerHTML=O.filter(o=>f==='all'||o[5]===f||(f==='shipped'&&o[5]==='paid'&&false)).map((o,i)=>`<tr><td><b>${o[0]}</b></td><td><div class="cust"><span style="background:${cols[i%7]}" aria-hidden="true">${o[1].split(' ').map(x=>x[0]).join('')}</span>${o[1]}</div></td><td>${o[2]}</td><td>${o[3]}</td><td><b>${o[4]}</b></td><td><span class="chip s-${o[5]}">${o[5][0].toUpperCase()+o[5].slice(1)}</span></td></tr>`).join('')||'<tr><td colspan="6">No orders in this view.</td></tr>'}
document.querySelectorAll('#filters button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#filters button').forEach(x=>x.setAttribute('aria-pressed',x===b));orders(b.dataset.f)}));orders('all');
const D={y:{l:["Nov","Dec","Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct"],v:[38,61,34,36,42,45,48,52,49,55,68,84]},w:{l:["Mon","Tue","Wed","Thu","Fri","Sat","Sun"],v:[2.1,2.8,2.4,3.3,4.1,5.2,3.9]}};
function bars(p){const d=D[p],svg=document.getElementById('rev'),W=svg.clientWidth||700,H=240,pb=26,pl=36,mx=Math.max(...d.v)*1.15,bw=(W-pl)/d.v.length;let g='';
for(let j=0;j<=4;j++){const y=H-pb-(H-pb-10)*j/4;g+=`<line x1="${pl}" x2="${W}" y1="${y}" y2="${y}" stroke="#EAE7E4"/><text x="${pl-6}" y="${y+4}" text-anchor="end" font-size="11" fill="#78716C">$${(mx*j/4).toFixed(p==='y'?0:1)}k</text>`}
d.v.forEach((v,i)=>{const h=(H-pb-10)*v/mx,x=pl+i*bw+bw*.2,last=i===d.v.length-1;g+=`<rect x="${x}" y="${H-pb-h}" width="${bw*.6}" height="${h}" rx="6" fill="${last?'#F97316':'#FED7B5'}"><title>${d.l[i]}: $${v}k</title></rect><text x="${x+bw*.3}" y="${H-8}" text-anchor="middle" font-size="11" fill="#78716C">${d.l[i]}</text>`});
svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML=g}
document.querySelectorAll('[data-p]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-p]').forEach(x=>x.setAttribute('aria-pressed',x===b));bars(b.dataset.p)}));
bars('y');window.addEventListener('resize',()=>bars(document.querySelector('[data-p][aria-pressed=true]').dataset.p));
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
